import sys

def min_spots(n, H):
    if n <= H:
        return n
    if n == H + 1:
        return 2
    remaining_sand = n - H - 1
    spots = 2
    while remaining_sand > 0:
        if remaining_sand >= spots:
            remaining_sand -= spots
            spots += 1
        else:
            spots += remaining_sand
            remaining_sand = 0
    return spots

if __name__ == "__main__":
    input = sys.stdin.read
    data = input().split()
    n = int(data[0])
    H = int(data[1])
    result = min_spots(n, H)
    print(result)

