import sys

def min_spots(n, H):
    if n <= H:
        return n
    elif n % (H + 1) == 0:
        return n // (H + 1)
    else:
        return n // (H + 1) + 1

if __name__ == "__main__":
    input = sys.stdin.read().strip()
    n, H = map(int, input.split())
    result = min_spots(n, H)
    print(result)
